@startuml

class WebPortal {
  + VersionNumber : string
  + URLAddress : string
}

class Building {
  + ID : string
  + Name : string
  + EnergyClass : string
  + Address : string
  + YearOfConstruction : int
}

class AdditionalEntry {
  + Name : string
  + IsPublic : boolean
}

class TextualEntry extends AdditionalEntry {
  + TextContent : string
}

class NumericalEntry extends AdditionalEntry {
  + Value : float
  + Unit : string
}

class Image {
  + FileName : string
  + IsProfilePhoto : boolean
}

class User {
  + UserName : string
  + EmailAddress : string
  + Password : string
  + IsActivated : boolean
}

class Administrator extends User {
  + IDCardNumber : string
}

class Comment {
  + Content : string
}

WebPortal "1" -- "*" Building : provides catalog of
WebPortal "1" -- "*" User : registers
WebPortal "1" -- "*" Administrator : manages
WebPortal "1" -- "*" Visitor : allows access to

Building "1" *-- "0..*" AdditionalEntry
Building "1" *-- "0..*" Image
Building "0..*" -- "1" User : owner

User "1" -- "*" Building : creates
User "1" -- "*" Comment : writes
User "1" -- "*" Building : comments on
Administrator "1" -- "*" User : sets up
Administrator "1" -- "*" Comment : deletes

class Visitor {}

Visitor "0..*" -- "*" Building : searches

@enduml

